insert into public.stories(id) values('red-umbrella') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella',1,'The Red Umbrella','English Tales','A1','Günlük yaşam','Yağmurlu bir günde paylaşılan şemsiye yeni bir dostluğa kapı açıyor.','a6eba49f-7b47-57af-a6ed-b36c348bbd13');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-1',1,'Anna looks out of her window.','Anna penceresinden dışarı bakar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-2',2,'The sky is gray, and rain falls on the street.','Gökyüzü gridir ve sokağa yağmur yağar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-3',3,'She needs bread and milk from the shop.','Dükkândan ekmek ve süt alması gerekir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-4',4,'She takes her red umbrella and opens the door.','Kırmızı şemsiyesini alır ve kapıyı açar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-5',5,'Her neighbor, Mrs. Green, is outside.','Komşusu Bayan Green dışarıdadır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-6',6,'Her coat is wet, and she looks cold.','Paltosu ıslaktır ve üşümüş görünür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-7',7,'Anna walks over and says hello.','Anna yanına yürür ve merhaba der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-8',8,'Mrs. Green needs to go to the same shop.','Bayan Green de aynı dükkâna gitmek zorundadır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-9',9,'Anna holds the umbrella above them both.','Anna şemsiyeyi ikisinin de üzerinde tutar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-10',10,'They walk slowly along the street.','Sokak boyunca yavaşça yürürler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-11',11,'At the shop, Anna buys bread and milk.','Dükkânda Anna ekmek ve süt alır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-12',12,'Mrs. Green buys apples for a cake.','Bayan Green kek yapmak için elma alır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-13',13,'Her bag is heavy, so Anna helps her.','Çantası ağırdır, bu yüzden Anna ona yardım eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-14',14,'On the way home, the rain stops.','Eve dönerken yağmur durur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-15',15,'A little bird sings in a tree.','Küçük bir kuş ağaçta öter.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-16',16,'Mrs. Green invites Anna in for tea.','Bayan Green, Anna’yı çay içmek için içeri davet eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-17',17,'They sit by the window and share the cake.','Pencerenin yanına oturur ve keki paylaşırlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ed834736-3125-5576-adaa-a092d538fdfc','red-umbrella-18',18,'Anna has a new friend and a good story to tell.','Anna’nın yeni bir arkadaşı ve anlatacak güzel bir hikâyesi vardır.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ed834736-3125-5576-adaa-a092d538fdfc','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ed834736-3125-5576-adaa-a092d538fdfc','rain','rain','yağmur','/reɪn/','The rain stops.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ed834736-3125-5576-adaa-a092d538fdfc','umbrella','umbrella','şemsiye','/ʌmˈbrelə/','She takes her red umbrella.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ed834736-3125-5576-adaa-a092d538fdfc','neighbor','neighbor','komşu','/ˈneɪbər/','Her neighbor is outside.');
