insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train',1,'The Last Train','English Tales','A2','Macera','Kaçırılmak üzere olan bir tren, iki arkadaş için beklenmedik bir yolculuğa dönüşüyor.','51cedeb2-1239-596c-a185-669a28375f22');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-1',1,'Sam and Lily spent the afternoon in a village near the mountains.','Sam ve Lily öğleden sonrayı dağların yakınındaki bir köyde geçirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-2',2,'They visited a market and took photos of the old houses.','Bir pazarı gezdiler ve eski evlerin fotoğraflarını çektiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-3',3,'When the sky grew dark, Lily checked her watch.','Hava karardığında Lily saatine baktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-4',4,'The last train was due in twenty minutes.','Son trenin gelmesine yirmi dakika vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-5',5,'They hurried to the station at the end of the village.','Köyün sonundaki istasyona aceleyle gittiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-6',6,'Sam reached into his pocket, but his ticket was missing.','Sam elini cebine attı ama bileti yerinde değildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-7',7,'He remembered putting it beside his camera at the market.','Pazarda bileti fotoğraf makinesinin yanına koyduğunu hatırladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-8',8,'Lily waited on the platform while Sam ran back.','Sam geri koşarken Lily peronda bekledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-9',9,'Most of the market stalls were already closed.','Pazardaki tezgâhların çoğu çoktan kapanmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-10',10,'A woman was packing the last box of flowers.','Bir kadın son çiçek kutusunu hazırlıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-11',11,'Sam asked her about the ticket, and she pointed to a bench.','Sam kadına bileti sordu, kadın da bir bankı işaret etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-12',12,'There it was, under a small stone.','Bilet oradaydı, küçük bir taşın altındaydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-13',13,'Sam thanked the woman and ran toward the station.','Sam kadına teşekkür etti ve istasyona doğru koştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-14',14,'He could hear the train coming around the hill.','Trenin tepenin öbür yanından geldiğini duyabiliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-15',15,'Lily waved from the platform as he arrived.','Sam vardığında Lily perondan el salladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-16',16,'They climbed aboard just before the doors closed.','Kapılar kapanmadan hemen önce trene bindiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-17',17,'Through the window, they watched the village lights disappear.','Pencereden köyün ışıklarının gözden kayboluşunu izlediler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3471421e-03c8-55ba-ae57-1785cf654c82','last-train-18',18,'Sam put the ticket safely in his pocket and finally began to laugh.','Sam bileti güvenli bir şekilde cebine koydu ve sonunda gülmeye başladı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','village','village','köy','/ˈvɪlɪdʒ/','They visited a small village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','market','market','pazar','/ˈmɑːrkɪt/','The market was busy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','station','station','istasyon','/ˈsteɪʃən/','They hurried to the station.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','pocket','pocket','cep','/ˈpɑːkɪt/','He put it in his pocket.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','ticket','ticket','bilet','/ˈtɪkɪt/','Sam found his ticket.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','platform','platform','peron','/ˈplætfɔːrm/','Lily waited on the platform.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','bench','bench','bank','/bentʃ/','The ticket was on a bench.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3471421e-03c8-55ba-ae57-1785cf654c82','safely','safely','güvenli bir şekilde','/ˈseɪfli/','He put the ticket safely in his pocket.');
