insert into public.stories(id) values('classic-lion-mouse') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('b1f40817-d171-5b18-a1b0-3a2c91900725','classic-lion-mouse',1,'The Lion and the Mouse','Aesop','A1','Macera','Aslan ve Fare. Küçük bir farenin büyük bir dostuna yardımı. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales.','a88cbc3b-c2b1-54f1-a2e6-d3689baaac15');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-01',1,'A lion sleeps under a tree.','Bir aslan ağacın altında uyur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-02',2,'A little mouse runs across his face.','Küçük bir fare yüzünün üzerinden koşar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-03',3,'The lion wakes up and catches the mouse.','Aslan uyanır ve fareyi yakalar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-04',4,'"Please let me go," says the mouse.','"Lütfen beni bırak," der fare.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-05',5,'"One day, I can help you."','"Bir gün sana yardım edebilirim."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-06',6,'The lion laughs at this little animal.','Aslan bu küçük hayvana güler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-07',7,'But he opens his paw and lets her go.','Ama pençesini açar ve onu bırakır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-08',8,'Later, hunters catch the lion.','Daha sonra avcılar aslanı yakalar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-09',9,'They tie him to the ground with strong ropes.','Onu sağlam iplerle yere bağlarlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-10',10,'The lion cannot move, and he roars.','Aslan hareket edemez ve kükrer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-11',11,'The mouse hears him and runs to help.','Fare onu duyar ve yardıma koşar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-12',12,'Her teeth are small but sharp.','Dişleri küçük ama keskindir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-13',13,'She bites through the ropes.','İpleri kemirerek koparır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-14',14,'Now the lion is free.','Artık aslan özgürdür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-15',15,'He thanks his tiny friend.','Minicik dostuna teşekkür eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('b1f40817-d171-5b18-a1b0-3a2c91900725','cl-lion-mouse-16',16,'Even a small friend can give great help.','Küçük bir dost bile büyük bir yardımda bulunabilir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('b1f40817-d171-5b18-a1b0-3a2c91900725','lion','lion','aslan','/ˈlaɪən/','The lion sleeps under a tree.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('b1f40817-d171-5b18-a1b0-3a2c91900725','mouse','mouse','fare','/maʊs/','The mouse is very small.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('b1f40817-d171-5b18-a1b0-3a2c91900725','paw','paw','pençe','/pɔː/','The lion opens his paw.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('b1f40817-d171-5b18-a1b0-3a2c91900725','ropes','ropes','ipler','/rəʊps/','The ropes are strong.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('b1f40817-d171-5b18-a1b0-3a2c91900725','teeth','teeth','dişler','/tiːθ/','The mouse has sharp teeth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('b1f40817-d171-5b18-a1b0-3a2c91900725','sharp','sharp','keskin','/ʃɑːp/','These teeth are sharp.');
