insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','classic-fox-grapes',1,'The Fox and the Grapes','Aesop','A1','Macera','Tilki ve Üzümler. Ulaşamadığı üzümler hakkında fikrini değiştiren bir tilki. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales.','64a62a72-1a19-5d14-ac64-fde1f1e738cd');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-01',1,'A hungry fox walks past a garden.','Aç bir tilki bir bahçenin yanından geçer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-02',2,'She sees some grapes on a vine.','Bir asmada üzümler görür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-03',3,'The grapes are dark and ripe.','Üzümler koyu renkli ve olgundur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-04',4,'"Those grapes look sweet," she says.','"Şu üzümler tatlı görünüyor," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-05',5,'She wants to eat them.','Onları yemek ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-06',6,'But the grapes are very high.','Ama üzümler çok yüksektedir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-07',7,'The fox jumps into the air.','Tilki havaya sıçrar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-08',8,'She cannot reach the grapes.','Üzümlere ulaşamaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-09',9,'She tries again and again.','Tekrar tekrar dener.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-10',10,'At last, she is tired.','Sonunda yorulur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-11',11,'She turns away from the vine.','Asmaya arkasını döner.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-12',12,'"Those grapes are sour," she says.','"Şu üzümler ekşi," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-13',13,'"They are not ripe at all."','"Hiç de olgun değiller."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-14',14,'She walks away without any grapes.','Hiç üzüm alamadan uzaklaşır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','cl-fox-grapes-15',15,'She hides her disappointment with unkind words.','Hayal kırıklığını kırıcı sözlerle gizler.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','fox','fox','tilki','/fɒks/','The fox sees some grapes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','grapes','grapes','üzümler','/ɡreɪps/','The grapes are high on the vine.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','vine','vine','asma','/vaɪn/','A vine grows in the garden.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','ripe','ripe','olgun','/raɪp/','The fruit is ripe.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','sour','sour','ekşi','/ˈsaʊə(r)/','The fox calls the grapes sour.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fe29e7d7-30c1-5878-abdd-69cf1f612c5b','disappointment','disappointment','hayal kırıklığı','/ˌdɪsəˈpɔɪntmənt/','She hides her disappointment.');
