insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('69677981-6492-5f69-a83d-0048bc5d43f1','classic-ants-grasshopper',1,'The Ants and the Grasshopper','Aesop','A1','Macera','Karıncalar ve Çekirge. Kış hazırlığı ile günü yaşama arasındaki farkı anlatan bir fabl. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales.','42ae2531-3afe-5b71-a902-0cb6f1aac3d0');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-01',1,'It is a bright winter day.','Aydınlık bir kış günüdür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-02',2,'Some ants bring their grain outside.','Birkaç karınca tahıllarını dışarı çıkarır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-03',3,'They spread it out to dry.','Kuruması için onu yere sererler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-04',4,'A grasshopper comes along the path.','Bir çekirge patikadan gelir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-05',5,'He is cold and hungry.','Üşümüştür ve açtır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-06',6,'"Please give me some food," he says.','"Lütfen bana biraz yiyecek verin," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-07',7,'The ants look at him.','Karıncalar ona bakar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-08',8,'"Why did you not store food in summer?" they ask.','"Yazın neden yiyecek biriktirmedin?" diye sorarlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-09',9,'"I was busy singing," says the grasshopper.','"Şarkı söylemekle meşguldüm," der çekirge.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-10',10,'"I sang all day long."','"Bütün gün şarkı söyledim."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-11',11,'The ants do not offer him any grain.','Karıncalar ona hiç tahıl vermez.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-12',12,'"You sang in summer," they say.','"Yazın şarkı söyledin," derler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-13',13,'"Now you can dance without supper."','"Şimdi de akşam yemeği yemeden dans edebilirsin."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-14',14,'The grasshopper has nothing to eat.','Çekirgenin yiyecek hiçbir şeyi yoktur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('69677981-6492-5f69-a83d-0048bc5d43f1','cl-ants-grasshopper-15',15,'Summer is the time to prepare for winter.','Yaz, kışa hazırlanma zamanıdır.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','winter','winter','kış','/ˈwɪntə(r)/','Winter is cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','ants','ants','karıncalar','/ænts/','The ants work together.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','grain','grain','tahıl','/ɡreɪn/','The ants store grain.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','dry','dry','kurutmak','/draɪ/','They spread the grain out to dry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','grasshopper','grasshopper','çekirge','/ˈɡrɑːshɒpə(r)/','The grasshopper spends the summer singing.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','path','path','patika','/pæθ/','A narrow path led uphill.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','store','store','biriktirmek','/stɔː(r)/','The ants store food for winter.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','supper','supper','akşam yemeği','/ˈsʌpə(r)/','The animals eat their supper.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('69677981-6492-5f69-a83d-0048bc5d43f1','prepare','prepare','hazırlanmak','/prɪˈpeə(r)/','We prepare for winter.');
