insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','classic-hansel-gretel',1,'Hansel and Gretel','Jacob and Wilhelm Grimm','A2','Macera','Hansel ve Gretel. Ormanda bırakılan iki kardeşin cesaret ve zekâyla eve dönüşü. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales.','57761491-8b15-57f1-ab20-4d285a385627');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-01',1,'Hansel and Gretel lived near a forest with their father and stepmother.','Hansel ile Gretel, babaları ve üvey anneleriyle bir ormanın yakınında yaşıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-02',2,'The family had so little food that the stepmother wanted to leave the children in the forest.','Ailenin yiyeceği o kadar azdı ki üvey anne çocukları ormanda bırakmak istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-03',3,'Their father finally agreed, although it made him unhappy.','Babaları, bu onu üzse de sonunda kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-04',4,'Hansel heard the plan and filled his pocket with white pebbles.','Hansel planı duydu ve cebini beyaz çakıl taşlarıyla doldurdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-05',5,'As they walked into the forest, he dropped the pebbles behind him.','Ormana yürürlerken çakıl taşlarını arkasına bıraktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-06',6,'That night, the children followed the shining stones home.','O gece çocuklar parlayan taşları izleyerek eve döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-07',7,'When the family ran out of food again, their stepmother took them farther away.','Ailenin yiyeceği yine tükenince üvey anneleri onları daha uzağa götürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-08',8,'This time, Hansel could only drop bread crumbs on the path.','Hansel bu kez patikaya yalnızca ekmek kırıntıları bırakabildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-09',9,'But birds ate the crumbs, and the children could not find their way back.','Ama kuşlar kırıntıları yedi ve çocuklar dönüş yolunu bulamadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-10',10,'After wandering for days, they followed a white bird to a strange little house.','Günlerce dolaştıktan sonra beyaz bir kuşu izleyerek tuhaf küçük bir eve ulaştılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-11',11,'Its walls were made of bread, its roof of cake, and its windows of sugar.','Duvarları ekmekten, çatısı kekten, pencereleri ise şekerdendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-12',12,'The hungry children began to eat pieces of the house.','Aç çocuklar evden parçalar yemeye başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-13',13,'An old woman invited them in and gave them food and beds.','Yaşlı bir kadın onları içeri davet edip yiyecek ve yatak verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-14',14,'But she was a witch who wanted to eat them.','Ama o, onları yemek isteyen bir cadıydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-15',15,'The next morning, she locked Hansel behind a barred door.','Ertesi sabah Hansel''i demir parmaklıklı bir kapının arkasına kilitledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-16',16,'Gretel had to cook meals to make her brother fat.','Gretel, kardeşini şişmanlatmak için yemekler pişirmek zorundaydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-17',17,'The witch could not see well and asked to feel Hansel''s finger.','Cadı iyi göremiyordu ve Hansel''in parmağını yoklamak istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-18',18,'He held out a little bone instead, so she thought he was still thin.','Hansel onun yerine küçük bir kemik uzattı, bu yüzden cadı onun hâlâ zayıf olduğunu sandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-19',19,'At last, the witch lost patience and decided to heat the oven.','Sonunda cadının sabrı tükendi ve fırını ısıtmaya karar verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-20',20,'She told Gretel to climb inside and check the heat.','Gretel''e içeri girip sıcaklığı kontrol etmesini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-21',21,'Gretel understood the danger and pretended not to know how.','Gretel tehlikeyi anladı ve nasıl yapacağını bilmiyormuş gibi davrandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-22',22,'When the witch leaned in to show her, Gretel pushed her into the oven.','Cadı ona göstermek için içeri eğildiğinde Gretel onu fırına itti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-23',23,'She shut the door, and the witch died inside.','Kapıyı kapattı ve cadı içeride öldü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-24',24,'Gretel freed her brother, and they hugged each other.','Gretel kardeşini kurtardı ve birbirlerine sarıldılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-25',25,'They found jewels in the house and filled their pockets.','Evde mücevherler bulup ceplerini doldurdular.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-26',26,'On the way home, a duck carried them across some water, one at a time.','Eve dönerken bir ördek onları suyun karşısına teker teker taşıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-27',27,'Soon they recognized the forest and found their father''s house.','Çok geçmeden ormanı tanıdılar ve babalarının evini buldular.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-28',28,'Their stepmother had died, and their father welcomed them with joy.','Üvey anneleri ölmüştü ve babaları onları sevinçle karşıladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','cl-hansel-gretel-29',29,'The jewels ended their hunger, and the family lived happily together.','Mücevherler açlıklarını sona erdirdi ve aile birlikte mutlu bir hayat sürdü.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','pocket','pocket','cep','/ˈpɑːkɪt/','He put it in his pocket.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','pebbles','pebbles','çakıl taşları','/ˈpeblz/','Hansel drops white pebbles.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','crumbs','crumbs','kırıntılar','/krʌmz/','Birds eat the bread crumbs.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','path','path','patika','/pæθ/','A narrow path led uphill.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','witch','witch','cadı','/wɪtʃ/','The old woman is a witch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','barred','barred','parmaklıklı','/bɑːd/','Hansel waits behind a barred door.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','bone','bone','kemik','/bəʊn/','He holds out a bone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','oven','oven','fırın','/ˈʌvn/','The oven is hot.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('35cf4e88-11a0-59a4-af98-d9273149f3ce','jewels','jewels','mücevherler','/ˈdʒuːəlz/','They find jewels in the house.');
