insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','flame','flame','alev','/fleɪm/','The flame lights his face.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','scar','scar','yara izi','/skɑː(r)/','A small scar marks his face.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','coat','coat','palto','/koʊt/','His coat is wet.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','detective','detective','dedektif','/dɪˈtektɪv/','The stranger is a detective.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','arrest','arrest','gözaltı','/əˈrest/','Bob is under arrest.');
